  [delivery] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
  [delivery_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
  [rowid] BIGINT IDENTITY(1,1) NOT NULL,
  CONSTRAINT [pk_platform_whatsapp_messages] PRIMARY KEY NONCLUSTERED ([batch_id], [contact_id]),
  CONSTRAINT [ck_platform_whatsapp_messages_1] CHECK ([state] IN ('pending','submitting','accepted','rejected','uncertain','skipped','rehearsed')),
  CONSTRAINT [ck_platform_whatsapp_messages_2] CHECK ([delivery] IN ('sent','delivered','read','failed'))
);
CREATE TABLE [platform_whatsapp_suppressions] (
  [organization_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [project_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [phone_hash] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [reason] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [created_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [rowid] BIGINT IDENTITY(1,1) NOT NULL,
  CONSTRAINT [pk_platform_whatsapp_suppressions] PRIMARY KEY NONCLUSTERED ([organization_id], [project_id], [phone_hash]),
  CONSTRAINT [ck_platform_whatsapp_suppressions_1] CHECK (LEN([phone_hash])=64),
  CONSTRAINT [ck_platform_whatsapp_suppressions_2] CHECK ([reason] IN ('team','reply'))
);
CREATE TABLE [platform_whatsapp_templates] (
  [connection_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [organization_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [project_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [name] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [language] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [category] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [body] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [params] BIGINT NOT NULL,
  [fetched_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [header_format] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT 'NONE',
  [button_url] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
  [button_index] BIGINT,
  [rowid] BIGINT IDENTITY(1,1) NOT NULL,
  CONSTRAINT [pk_platform_whatsapp_templates] PRIMARY KEY NONCLUSTERED ([connection_id], [name], [language]),
  CONSTRAINT [ck_platform_whatsapp_templates_1] CHECK ([header_format] IN ('NONE','TEXT','IMAGE','VIDEO','DOCUMENT'))
);
CREATE TABLE [platform_work_items] (
  [id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [organization_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [project_id] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [title] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [campaign_id] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
  [due_at] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [status] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [note] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '',
  [created_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [rowid] BIGINT IDENTITY(1,1) NOT NULL,
  CONSTRAINT [pk_platform_work_items] PRIMARY KEY NONCLUSTERED ([id])
);
CREATE TABLE [platform_worker_observations] (
  [component] NVARCHAR(170) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [run_id] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [first_observed_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [started_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [finished_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
  [outcome] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [last_success_at] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
  [checked] BIGINT NOT NULL DEFAULT 0,
  [failed] BIGINT NOT NULL DEFAULT 0,
  [consecutive_failures] BIGINT NOT NULL DEFAULT 0,
  [rowid] BIGINT IDENTITY(1,1) NOT NULL,
  CONSTRAINT [pk_platform_worker_observations] PRIMARY KEY NONCLUSTERED ([component]),
  CONSTRAINT [ck_platform_worker_observations_1] CHECK ([component]='platform-worker'),
  CONSTRAINT [ck_platform_worker_observations_2] CHECK ([outcome] IN ('running','completed','partial','failed')),
  CONSTRAINT [ck_platform_worker_observations_3] CHECK ([checked] BETWEEN 0 AND 3),
  CONSTRAINT [ck_platform_worker_observations_4] CHECK ([failed] BETWEEN 0 AND 3),
  CONSTRAINT [ck_platform_worker_observations_5] CHECK ([consecutive_failures] BETWEEN 0 AND 1000000)
);

